// (DESIGN 6, 8 chapter 2), and the three quests DESIGN 14.8 writes out. The chapters themselves come with P1.E09.T07 and
// T08, boards are generated by P1.E09.T06, and the Forty Names registry and its logs with P1.E09.T09; each adds its
// quests here (or generates them) in this shape. packages/shared/test/quests.test.ts validates every one against the
// schema and its references against the data tables and the galaxy.
import { deepFreeze } from '../data/index.ts';
