/** The Ulgani home system, Belost's (galaxy index; `homeSystems()` puts the Ulgani at 1). */
export const BELOST_SYSTEM = 1;
/** A Tier 2 system with a third planet: Rolis, whose third planet is body 2 (DESIGN 14.8's "Vexmir III" is a placeholder
 * name; the world generator names this one). */
export const ROLIS_SYSTEM = 5;
export const ROLIS_III = 2;

/** The apothecary's stall in Belost's market, beside its trade post on the plaza (the capital of the Ulgani home world,
 * on the ground the shared city plan levels). DESIGN 14.8's "under the north cap" placed her at the world's pole, far
 * from any city and over water; she keeps shop in the capital instead (an orchestrator decision). */
const APOTHECARY_STALL: Place = { system: BELOST_SYSTEM, body: 'home', city: { city: 'capital', spot: 'market', v: 14 }, radius: 250 };

