/** A development server's quest: its one step plays the test cutscene, started by the server (as a quest step's cutscene
 * is), for the online smoke and for trying cutscenes on a dev server. A client takes it without an offer there only. */
export const CUTSCENE_TEST_QUEST: QuestDef = deepFreeze<QuestDef>({
  id: 'cutscene_test',
  title: 'The Test Cutscene',
  category: 'personal',
  giver: 'terminal:dev',
  dev: true,
  prerequisites: {},
  steps: [{ id: 'watch', type: 'cutscene', text: 'Watch the test cutscene', cutscene: 'test' }],
  rewards: {},
  flags: [],
  repeat: { cooldownS: 60 },
});

const BY_ID: ReadonlyMap<string, QuestDef> = new Map([...QUESTS, CUTSCENE_TEST_QUEST].map((q) => [q.id, q]));

/** A quest by id, or undefined (a saved state may name a quest this build no longer has). */
export function getQuest(id: string): QuestDef | undefined {
  return BY_ID.get(id);
}

/** The quests started for every character that can take them, in catalog order. */
export const AUTO_QUESTS: readonly string[] = QUESTS.filter((q) => q.auto).map((q) => q.id);
